mapper.select:
SELECT ri.id,ri.room_number,ri.rent,ai.id as apartment_id,ai.* FROM `room_info` AS ri
LEFT JOIN apartment_info as ai ON ri.apartment_id=ai.id and ai.is_deleted=0
 ri.is_deleted=0 and ri.is_release=1 and ri.id not in (
    SELECT room_id FROM lease_agreement WHERE is_deleted = 0 AND `status`IN(2,5) )

        and ai.provice_id = #{queryVo.provinceId}


        and ai.city_id = #{queryVo.cityId}


        and ai.district_id =#{queryVo.districtId}


        and ri.rent >= #{queryVo.minRent}


        and ri.rent <= #{queryVo.maxRent}


        AND ri.id IN

            #{id}





    order by ri.rent ${queryVo.orderType}
